trait Describe { fn describe(&self) -> String; }
struct Record<'a, const N: usize> { title: &'a str, values: [u32; N] }
impl<'a, const N: usize> Describe for Record<'a, N> {
    fn describe(&self) -> String { format!("{}: {}", self.title, self.values.len()) }
}
fn first<'a, T>(items: &'a [T]) -> Option<&'a T> { items.first() }
async fn load(value: u32) -> u32 { async { value + 1 }.await }
macro_rules! total { ($($value:expr),*) => { 0 $(+ $value)* }; }
fn main() {
    let record = Record { title: "星空 🌌", values: [2, 4, 8] };
    let result = record.describe();
    let raw = r##"{ "value": "raw" }"##;
    let byte = b'x';
    let Some(head) = first(&record.values) else { return; };
    assert_eq!(*head, 2);
    assert_eq!(total!(1, 2, 3), 6);
    assert!(result.contains("星空"));
    let _ = (raw, byte);
}

